@Override
default void close() {}

record Device(String deviceId, byte[] publicKey, String role, long revision,
              java.util.Optional<java.time.Instant> revokedAt) {
    public Device(String deviceId, byte[] publicKey, String role) {
        this(deviceId, publicKey, role, 0, java.util.Optional.empty());
    }

    public Device(String deviceId, byte[] publicKey, HostRole role, long revision,
                  java.util.Optional<java.time.Instant> revokedAt) {
        this(deviceId, publicKey, role.name().toLowerCase(java.util.Locale.ROOT).replace('_', '-'),
                revision, revokedAt);
    }

    public Device {
        if (deviceId == null || deviceId.isBlank() || publicKey == null || publicKey.length < 32
                || role == null || role.isBlank() || revision < 0) {
            throw new IllegalArgumentException("invalid paired device");
        }
        hostRole(role);
        publicKey = publicKey.clone();
        revokedAt = revokedAt == null ? java.util.Optional.empty() : revokedAt;
    }

    @Override public byte[] publicKey() { return publicKey.clone(); }
    public HostRole hostRole() { return hostRole(role); }
    public boolean active() { return revokedAt.isEmpty(); }
    @Override public String toString() { return "Device[deviceId=" + deviceId + ",role=" + role + "]"; }

    private static HostRole hostRole(String value) {
        return HostRole.valueOf(value.replace('-', '_').toUpperCase(java.util.Locale.ROOT));
    }
}
